"""UART CPU-driven SoC functional-test catalogue."""

from __future__ import annotations

import argparse
import sys
from dataclasses import dataclass
from pathlib import Path


MODEL_DIR = Path(__file__).resolve().parent
RUN_ROOT = MODEL_DIR.parents[2]
UART_MODEL = RUN_ROOT / "ips" / "uart" / "dv" / "functional" / "model"
sys.path.insert(0, str(UART_MODEL))

from uart_model import BIT_CYCLES, uart_frame  # noqa: E402
import uart_regmap as regmap  # noqa: E402


CSR = regmap.PRIMARY
TESTS = ("uart_smoke",)
RX_BYTE = 0xA5
TEST_READY_RX = 0x52584459
TEST_READY_TX = 0x54584459
TEST_PASS = 0x55415254


@dataclass(slots=True)
class TestCase:
    config: list[str]
    data_in: list[str]
    data_out: list[str]


def drive(cycle: int, signal: str, value: int) -> str:
    return f"{cycle} {signal} 0x{value & 0xFFFF_FFFF:08x}"


def wait_event(cycle: int, name: str, value: int, timeout: int = 2048) -> str:
    """Start a cycle-relative phase after one firmware event value."""

    return f"{cycle} @wait_event {name} 0x{value:08x} {timeout}"


def wait_signal(cycle: int, signal: str, value: int, timeout: int = 2048) -> str:
    """Start a cycle-relative phase when one observable signal matches."""

    return f"{cycle} @wait_signal {signal} 0x{value:08x} {timeout}"


def check(cycle: int, signal: str, value: int) -> str:
    return f"{cycle} {signal} 0x{value & 0xFFFF_FFFF:08x}"


def uart_smoke() -> TestCase:
    """Inject RX only after firmware configures UART, then let firmware echo it."""

    data_in = [drive(0, "rx_i", 1), wait_event(1, "READY_RX", TEST_READY_RX)]
    cycle = BIT_CYCLES
    for bit in uart_frame(RX_BYTE):
        data_in.append(drive(cycle, "rx_i", bit))
        cycle += BIT_CYCLES
    data_in.append(drive(cycle, "rx_i", 1))

    frame = uart_frame(RX_BYTE)
    data_out = [
        wait_event(0, "READY_TX", TEST_READY_TX),
        wait_signal(0, "tx_o", 0),
    ]
    cycle = BIT_CYCLES + BIT_CYCLES // 2
    for bit in frame[1:]:
        data_out.append(check(cycle, "tx_o", bit))
        cycle += BIT_CYCLES
    data_out.append(wait_event(cycle, "PASS", TEST_PASS))
    return TestCase(config=[], data_in=data_in, data_out=data_out)


def test_case(test: str) -> TestCase:
    scenarios = {"uart_smoke": uart_smoke}
    try:
        return scenarios[test]()
    except KeyError as exc:
        raise ValueError(f"unknown test {test!r}; choose one of {TESTS}") from exc


def write_test(root: str | Path, test: str) -> None:
    case = test_case(test)
    folder = Path(root) / test
    folder.mkdir(parents=True, exist_ok=True)
    regmap.write_config(folder / "config.regs", case.config)
    (folder / "data_in.vec").write_text(
        "# UART SoC stimulus generated by model/tests.py.\n"
        "# @wait_event/@wait_signal start a new cycle-relative phase.\n"
        + "\n".join(case.data_in) + "\n",
        encoding="utf-8",
    )
    (folder / "data_out.vec").write_text(
        "# UART TX expectations are synchronized by generic vector barriers.\n"
        + ("\n".join(case.data_out) + "\n" if case.data_out else ""),
        encoding="utf-8",
    )


def write_all_tests(root: str | Path, tests: list[str] | tuple[str, ...] | None = None) -> None:
    for test in tests or TESTS:
        write_test(root, test)


def main() -> int:
    parser = argparse.ArgumentParser(description="Generate UART SoC functional vectors.")
    parser.add_argument("--tests-dir", default="../tests")
    parser.add_argument("--test", action="append", default=[])
    parser.add_argument("--list", action="store_true")
    args = parser.parse_args()
    if args.list:
        print("\n".join(TESTS))
        return 0
    write_all_tests(args.tests_dir, args.test or None)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
